package manifest

import (
	"bytes"
	"fmt"
	"go/format"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// The generated files, slash paths from the module root.
const (
	// KopGen holds every kop entry's constant and its name registration.
	KopGen = "dirac/kop/manifest_gen.go"
	// DiracGen holds the dirac entries' (key, mech) constants and tables.
	DiracGen = "dirac/manifest_gen.go"
	// KgenGen holds kgen's enum and mask registrations of the kop entries.
	KgenGen = "dirac/kgen/manifest_names_gen.go"
)

// GenHeader starts every generated file.
const GenHeader = "// Code generated by kmanifest; DO NOT EDIT."

const kopImport = "github.com/adams-shaun/gorge/dirac/kop"

// GenFiles are the generated files' paths, sorted.
var GenFiles = []string{DiracGen, KgenGen, KopGen}

// Generate renders the generated files of a validated tree. The format keeps
// one entry from rewriting another's lines: one declaration per entry with an
// explicit value, entries separated by a blank line, sorted by family and
// value. Status is never written, so an activation changes no generated byte.
// A Next entry is rendered at its provisional value. The dirac file also
// holds the dispatch of t.Handlers (ScanKernel): execExtGen, execOpGen,
// askOptionsGen and applyAskGen.
func Generate(t *Tree) (map[string][]byte, error) {
	es := append([]*Entry(nil), t.Entries...)
	sort.SliceStable(es, func(i, j int) bool {
		a, b := es[i], es[j]
		if a.Family != b.Family {
			return a.Family < b.Family
		}
		if a.Value != b.Value {
			return a.Value < b.Value
		}
		return a.Name < b.Name
	})
	var kop, dirac, kgen bytes.Buffer
	for _, e := range es {
		f := e.Fam()
		out := &kop
		if f.Pkg == "dirac" {
			out = &dirac
		}
		fmt.Fprintf(out, "\n// %s (%s)\n", genLabel(e), e.Path)
		if e.Doc != "" {
			fmt.Fprintf(out, "//\n// %s\n", e.Doc)
		}
		fmt.Fprintf(out, "const %s %s = %s\n", e.Name, f.goType(), genValue(e))
		if f.register != nil && (f.Cover == 0 || e.Value < f.Cover) {
			out.WriteString(genInit(f.register(e)))
		}
		if f.Kgen != "" {
			fmt.Fprintf(&kgen, "\n// %s\nfunc init() { %s[kop.%s](%q, kop.%s) }\n", e.Path, f.Kgen, f.Name, "kop."+e.Name, e.Name)
		}
	}
	if n, ok := numMech(es); ok {
		fmt.Fprintf(&dirac, "\n// numMech is one past the highest mech: the length of the arena's mech tables.\nconst numMech mech = %d\n", n)
	}
	dirac.WriteString(genKernelDispatch(t.Handlers))
	if len(t.Handlers.Word) > 0 {
		dirac.WriteString(genFilterWords(t.Handlers))
	}
	kgenHead := "package kgen\n"
	if kgen.Len() > 0 {
		kgenHead += "\nimport " + `"` + kopImport + `"` + "\n"
	}
	files := map[string][]byte{
		KopGen:   genFile("package kop\n", kop.Bytes()),
		DiracGen: genFile("package dirac\n\nimport "+`"`+kopImport+`"`+"\n", dirac.Bytes()),
		KgenGen:  genFile(kgenHead, kgen.Bytes()),
	}
	for _, p := range GenFiles {
		f, err := format.Source(files[p])
		if err != nil {
			return nil, fmt.Errorf("%s: %v", p, err)
		}
		files[p] = f
	}
	return files, nil
}

// numMech is one past the highest mech value, and whether there is a mech.
func numMech(es []*Entry) (int64, bool) {
	n, ok := int64(0), false
	for _, e := range es {
		if e.Family == "mech" {
			n, ok = max(n, e.Value+1), true
		}
	}
	return n, ok
}

func genFile(head string, body []byte) []byte {
	return append([]byte(GenHeader+"\n\n"+head), body...)
}

// genInit is an init function running stmts (one per line).
func genInit(stmts string) string {
	if !strings.Contains(stmts, "\n") {
		return "\nfunc init() { " + stmts + " }\n"
	}
	return "\nfunc init() {\n\t" + strings.ReplaceAll(stmts, "\n", "\n\t") + "\n}\n"
}

// genValue is e's value as Go: a shift for a flag bit, decimal otherwise.
func genValue(e *Entry) string {
	if e.Fam().Bits {
		return fmt.Sprintf("1 << %d", bitOf(e.Value))
	}
	return fmt.Sprint(e.Value)
}

// genLabel names e's vocabulary item in its constant's comment: the census
// row's kind and item (its words up to the first key=value), else the forge
// tokens, else the family.
func genLabel(e *Entry) string {
	if e.Census != "" {
		var words []string
		for _, w := range strings.Fields(e.Census) {
			if strings.Contains(w, "=") {
				break
			}
			words = append(words, w)
		}
		if len(words) > 0 {
			return strings.Join(words, " ")
		}
	}
	if len(e.Forge) > 0 {
		return strings.Join(e.Forge, " | ")
	}
	return e.Family
}

// WriteGen loads the manifest of the module at root and writes each generated
// file whose bytes differ, returning their paths. With check it writes
// nothing and returns the paths that are stale. A second run is a no-op.
func WriteGen(root string, check bool) ([]string, error) {
	t, err := LoadGen(os.DirFS(root))
	if err != nil {
		return nil, err
	}
	return writeGen(root, t, check)
}

// LoadGen is Load plus the kernel's handlers (ScanKernel): what
// Generate renders.
func LoadGen(fsys fs.FS) (*Tree, error) {
	t, err := Load(fsys)
	if err != nil {
		return nil, err
	}
	if t.Handlers, err = ScanKernel(fsys); err != nil {
		return nil, err
	}
	return t, nil
}

func writeGen(root string, t *Tree, check bool) ([]string, error) {
	files, err := Generate(t)
	if err != nil {
		return nil, err
	}
	var changed []string
	for _, p := range GenFiles {
		path := filepath.Join(root, filepath.FromSlash(p))
		old, err := os.ReadFile(path)
		if err == nil && bytes.Equal(old, files[p]) {
			continue
		}
		changed = append(changed, p)
		if check {
			continue
		}
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return changed, err
		}
		if err := os.WriteFile(path, files[p], 0o644); err != nil {
			return changed, err
		}
	}
	return changed, nil
}
